39	// ── smem arena for one A(64x16) + one B(Nmax x16) bf16 tile (the unpipelined
40	//    engine reuses two buffers across k-steps). Nmax = 128. 16B aligned. ──────
41	// Full-shape fwd: M = TILE_M (token rows), N_total = Nout (tiled into N=128/96
42	// atoms by the caller loop), K = Kin. Exercises N-tiling (Nout=512 → 4 tiles).
43	template <int N>
44	__global__ void __launch_bounds__(256)
45	gemm_fwd_kernel(const __nv_bfloat16* __restrict__ X,   // [M, Kin] row-major
46	                const __nv_bfloat16* __restrict__ W,   // [Nout, Kin] row-major
47	                float* __restrict__ D,                 // [M, Nout] row-major out
48	                int Kin, int Nout) {
49	#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 900)
50	    extern __shared__ __nv_bfloat16 smem[];
51	    __nv_bfloat16* sA = smem;
52	    __nv_bfloat16* sB = sA + 64 * 16;          // A is 64x16
53	    const int M = dectc::kTileM;
54	    const int m_atoms = M / 64;
55	    const int k_steps = Kin / 16;
56	    // Loop N-tiles of width N over [0, Nout). (fwd) D[m,n] = Σ_k X[m,k]·W[n,k].
57	    for (int n0 = 0; n0 < Nout; n0 += N) {
58	        const int n_real = (Nout - n0) < N ? (Nout - n0) : N;
59	        auto srcA = [&] (int m, int k) -> __nv_bfloat16 { return X[(int64_t)m * Kin + k]; };
60	        auto srcB = [&] (int n, int k) -> __nv_bfloat16 {
61	            int nn = n0 + n; return nn < Nout ? W[(int64_t)nn * Kin + k] : __float2bfloat16(0.f); };
62	        auto out  = [&] (int m, int n, float v) { if (m < M) D[(int64_t)m * Nout + n0 + n] = v; };
63	        dectc::tc_gemm_block_unpipelined<N, /*MaxAtomsM=*/2>(
64	            0, m_atoms, n_real, k_steps, srcA, srcB, out, sA, sB);
65	    }
66	#else
67	    (void)X; (void)W; (void)D; (void)Kin; (void)Nout;
68	#endif
69	}
