1	#ifndef SG_FUSED_SM90_FUSED_DECODER_MEGAKERNEL_CUH_
2	#define SG_FUSED_SM90_FUSED_DECODER_MEGAKERNEL_CUH_
3	// ============================================================================
4	// csrc/fused/sm_90/fused_decoder_megakernel.cuh — PHASE 1 of the TRUE L3 fused
5	// megakernel. ONE persistent kernel per training step runs the REAL transformer-
6	// decoder forward+backward AND the AdamW optimizer math, separated only by
7	// in-kernel grid barriers — real model math, real optimizer math, ZERO
8	// intermediate kernel launches.
9	//
10	// This composes:
11	//   * the REAL decoder fwd/bwd stages (model_stages_decoder.cuh — transcribed
12	//     line-for-line from the verified PyTorch oracle, asserted bit-identical to
13	//     autograd, and structurally mirrored on CPU),
14	//   * the existing persistent substrate (megakernel_common.cuh: task queue, the
15	//     hand-built sense-reversing GridBarrier),
16	//   * the existing REAL optimizer tail (opt_components.cuh::apply_optimizer<Opt>).
17	//
18	// STAGE / BARRIER LAYOUT (5 phases, 4 grid barriers — see the per-stage comments):
19	//   P0  zero the per-CTA grad-partial workspace + per-CTA loss slots (each CTA
20	//       zeroes its OWN slice — no cross-CTA contention, no host memset needed).
21	//   --- grid barrier (B0): all partials zeroed before any accumulation ---
22	//   P1  BATCH-PARALLEL fwd+bwd: each CTA owns a FIXED contiguous batch slice
23	//       (by blockIdx.x), processes its samples ONE AT A TIME (CTA-cooperative),
24	//       accumulating each sample's weight-grad contribution into the CTA's OWN
25	//       partial buffer (gw + cta*total) with a single-owner-thread-per-element
26	//       rule (no atomics → deterministic), and summing its slice's NLL (fp32)
27	//       into the CTA's loss slot.
28	//   --- grid barrier (B1): all CTAs' partials + loss complete ---
29	//   P2  DETERMINISTIC cross-CTA reduce: sum partial[0..nCTA) in ASCENDING CTA
30	//       index into the global `grad` buffer (no float atomics; the per-element
31	//       summation ORDER is fixed, so the work-steal queue MAY pick who reduces
32	//       which element-range — determinism is in the order, not the picker). The
33	//       loss slots are summed in fp64 → one device float (loss/B), by CTA 0.
34	//   --- grid barrier (B2): reduced grad ready in global ---
35	//   P3  the existing apply_optimizer<AdamW> tail consumes the reduced grad
36	//       in-place over the flat param (work-steal queue over the 30 tensors).
37	//   (no barrier after P3 — kernel exits; the step is complete.)
38	//
39	// HONESTY: no placeholder math anywhere on this path. fp32 compute is the
40	// correctness baseline; a bf16-compute follow-up would be a flag defaulting to
41	// THIS fp32 path (not yet wired — see the report).
42	// ============================================================================
