56	// Rebase a FusedOptState's per-element state pointers to a parameter-tensor
57	// slice at `off` within the flat [m|v|extra] layout. Per-TENSOR fields (the
58	// NeuralGrok psi MLP weights) and all scalars pass through unchanged.
59	template <OptId Opt>
60	__device__ __forceinline__ FusedOptState
61	rebase_state(const FusedOptState& s, int64_t off) {
62	    FusedOptState t = s;  // scalars + per-tensor pointers copy as-is
63	    if (t.exp_avg)    t.exp_avg    += off;
64	    if (t.exp_avg_sq) t.exp_avg_sq += off;
65	    if (t.ema)        t.ema        += off;
66	    if (t.sam_dir)    t.sam_dir    += off;
67	    if (t.s_track)    t.s_track    += off;
68	    if (t.mu)         t.mu         += off;
69	    if (t.orth)       t.orth       += off;
70	    if (t.smart_grad) t.smart_grad += off;
71	    return t;
72	}
